                if (errptr)
                        *errptr = quote;
                goto leave;
        }
 leave:
        *nbargs = arg;
        *outlen = outpos;

        while (arg < argsmax)
                args[arg++] = out + outpos - 1;

        return err;
}
#undef EMIT_CHAR

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <file>\n", argv[0]); return 1; }
    FILE *f = fopen(argv[1], "rb");
